import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { user, logout, cart } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (location.pathname === '/catalog') {
      const searchParams = new URLSearchParams(location.search);
      const searchQuery = searchParams.get('search');
      if (searchQuery) {
        setSearchTerm(searchQuery);
      }
    }
  }, [location]);

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/catalog?search=${encodeURIComponent(searchTerm.trim())}`);
    } else {
      navigate('/catalog');
    }
    setIsSearchFocused(false);
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const clearSearch = () => {
    setSearchTerm('');
    if (location.pathname === '/catalog') {
      navigate('/catalog');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch(e);
    } else if (e.key === 'Escape') {
      setIsSearchFocused(false);
    }
  };

  const goToProfileTab = (tab) => {
    if (tab === 'profile') {
      navigate('/profile');
    } else {
      navigate(`/profile?tab=${tab}`);
    }
    setIsMobileMenuOpen(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
    setIsMobileMenuOpen(false);
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <nav className="bg-white shadow-lg border-b">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center flex-shrink-0">
            <img src="./images/logo.png" alt="LUNA AUREA" className="h-8 w-auto" />
            <span className="ml-2 text-xl font-serif font-bold hidden sm:block">LUNA AUREA</span>
            <span className="ml-2 text-xl font-serif font-bold sm:hidden">LA</span>
          </Link>

          {/* Desktop Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600 transition-colors">КАТАЛОГ</Link>
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600 transition-colors">КОЛЛЕКЦИИ</Link>
            <Link to="/about" className="text-gray-700 hover:text-gold-600 transition-colors">О НАС</Link>
            <Link to="/contacts" className="text-gray-700 hover:text-gold-600 transition-colors">КОНТАКТЫ</Link>
          </div>

          {/* Desktop Icons */}
          <div className="hidden md:flex items-center space-x-4">
            {/* Search */}
            <div className="relative">
              <form onSubmit={handleSearch} className="relative">
                <input
                  type="text"
                  placeholder="Поиск товаров..."
                  value={searchTerm}
                  onChange={handleSearchChange}
                  onKeyDown={handleKeyPress}
                  onFocus={() => setIsSearchFocused(true)}
                  onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}
                  className="pl-4 pr-10 py-2 border border-gray-300 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500 focus:border-gold-500 w-64 transition-all"
                />
                <div className="absolute right-2 top-1/2 transform -translate-y-1/2 flex space-x-1">
                  {searchTerm && (
                    <button
                      type="button"
                      onClick={clearSearch}
                      className="text-gray-400 hover:text-gray-600 p-1"
                    >
                      ✕
                    </button>
                  )}
                  <button
                    type="submit"
                    className="text-gray-400 hover:text-gold-600 p-1 transition-colors"
                  >
                    🔍
                  </button>
                </div>
              </form>
            </div>

            {/* Profile Dropdown */}
            {user ? (
              <div className="relative group">
                <button className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                  👤
                </button>
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200">
                  <button
                    onClick={() => navigate('/profile')}
                    className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                  >
                    Мой профиль
                  </button>
                  <button
                    onClick={() => goToProfileTab('orders')}
                    className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                  >
                    Мои заказы
                  </button>
                  <button
                    onClick={handleLogout}
                    className="block w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-gray-100 transition-colors"
                  >
                    Выйти
                  </button>
                </div>
              </div>
            ) : (
              <Link to="/auth" className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                👤
              </Link>
            )}

            {/* Favorites */}
            <button 
              onClick={() => user ? goToProfileTab('favorites') : navigate('/auth')}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              ❤️
            </button>

            {/* Cart */}
            <button 
              onClick={() => user ? goToProfileTab('cart') : navigate('/auth')}
              className="p-2 hover:bg-gray-100 rounded-full relative transition-colors"
            >
              🛒
              {user && cart && cart.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                  {cart.length}
                </span>
              )}
            </button>
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center space-x-2">
            {/* Mobile Search Button */}
            <button
              onClick={() => setIsSearchFocused(!isSearchFocused)}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              🔍
            </button>

            {/* Mobile Cart */}
            <button 
              onClick={() => user ? goToProfileTab('cart') : navigate('/auth')}
              className="p-2 hover:bg-gray-100 rounded-full relative transition-colors"
            >
              🛒
              {user && cart && cart.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                  {cart.length}
                </span>
              )}
            </button>

            {/* Mobile menu toggle */}
            <button
              onClick={toggleMobileMenu}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              {isMobileMenuOpen ? '✕' : '☰'}
            </button>
          </div>
        </div>

        {/* Mobile Search */}
        {isSearchFocused && (
          <div className="md:hidden pb-4">
            <form onSubmit={handleSearch} className="relative">
              <input
                type="text"
                placeholder="Поиск товаров..."
                value={searchTerm}
                onChange={handleSearchChange}
                onKeyDown={handleKeyPress}
                className="w-full pl-4 pr-10 py-2 border border-gray-300 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500"
              />
              <div className="absolute right-2 top-1/2 transform -translate-y-1/2 flex space-x-1">
                {searchTerm && (
                  <button
                    type="button"
                    onClick={clearSearch}
                    className="text-gray-400 hover:text-gray-600 p-1"
                  >
                    ✕
                  </button>
                )}
                <button
                  type="submit"
                  className="text-gray-400 hover:text-gold-600 p-1"
                >
                  🔍
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-gray-200 py-4">
            {/* Mobile Navigation Links */}
            <div className="flex flex-col space-y-4 mb-4">
              <Link 
                to="/catalog" 
                className="text-gray-700 hover:text-gold-600 transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КАТАЛОГ
              </Link>
              <Link 
                to="/catalog" 
                className="text-gray-700 hover:text-gold-600 transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОЛЛЕКЦИИ
              </Link>
              <Link 
                to="/about" 
                className="text-gray-700 hover:text-gold-600 transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                О НАС
              </Link>
              <Link 
                to="/contacts" 
                className="text-gray-700 hover:text-gold-600 transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОНТАКТЫ
              </Link>
            </div>

            {/* Mobile User Actions */}
            <div className="border-t border-gray-200 pt-4">
              {user ? (
                <div className="space-y-2">
                  <button
                    onClick={() => {
                      navigate('/profile');
                      setIsMobileMenuOpen(false);
                    }}
                    className="block w-full text-left py-2 text-gray-700 hover:text-gold-600 transition-colors"
                  >
                    👤 Мой профиль
                  </button>
                  <button
                    onClick={() => goToProfileTab('favorites')}
                    className="block w-full text-left py-2 text-gray-700 hover:text-gold-600 transition-colors"
                  >
                    ❤️ Избранное
                  </button>
                  <button
                    onClick={() => goToProfileTab('orders')}
                    className="block w-full text-left py-2 text-gray-700 hover:text-gold-600 transition-colors"
                  >
                    📦 Мои заказы
                  </button>
                  <button
                    onClick={handleLogout}
                    className="block w-full text-left py-2 text-red-600 hover:text-red-700 transition-colors"
                  >
                    🚪 Выйти
                  </button>
                </div>
              ) : (
                <Link 
                  to="/auth"
                  className="block py-2 text-gray-700 hover:text-gold-600 transition-colors"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  👤 Войти / Регистрация
                </Link>
              )}
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
